package com.bakeflow.inventory.infrastructure.web;
import com.bakeflow.inventory.application.*;import com.bakeflow.inventory.application.InventoryDtos.*;import java.net.URI;import java.time.LocalDate;import java.util.UUID;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/batches")public class BatchController{private final InventoryCatalogService service;BatchController(InventoryCatalogService s){service=s;}
@GetMapping public PageResult<BatchView>list(@RequestParam(required=false)UUID itemId,@RequestParam(required=false)String code,@RequestParam(required=false)Boolean active,@RequestParam(required=false)LocalDate expirationFrom,@RequestParam(required=false)LocalDate expirationTo,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.searchBatches(itemId,code,active,expirationFrom,expirationTo,page,size);}
@GetMapping("/{id}")public BatchView get(@PathVariable UUID id){return service.getBatch(id);}@PostMapping public ResponseEntity<BatchView>create(@RequestBody BatchInput input){var b=service.createBatch(input);return ResponseEntity.created(URI.create("/api/v1/batches/"+b.id())).body(b);}@PutMapping("/{id}")public BatchView update(@PathVariable UUID id,@RequestBody BatchInput input){return service.updateBatch(id,input);}@PatchMapping("/{id}/activate")public BatchView activate(@PathVariable UUID id){return service.setBatchActive(id,true);}@PatchMapping("/{id}/deactivate")public BatchView deactivate(@PathVariable UUID id){return service.setBatchActive(id,false);}}
